window.particlesJS=function(id,config){const host=document.getElementById(id);if(!host)return;const canvas=document.createElement("canvas");const ctx=canvas.getContext("2d");host.appendChild(canvas);const colors=config.particles.color.value;const count=config.particles.number.value;const dots=Array.from({length:count},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,r:2+Math.random()*5,vx:-.6+Math.random()*1.2,vy:.2+Math.random()*1,c:colors[Math.floor(Math.random()*colors.length)]}));function size(){canvas.width=innerWidth;canvas.height=innerHeight}function draw(){size();ctx.clearRect(0,0,canvas.width,canvas.height);dots.forEach(d=>{d.x+=d.vx;d.y+=d.vy;if(d.y>canvas.height+10)d.y=-10;if(d.x<-10)d.x=canvas.width+10;if(d.x>canvas.width+10)d.x=-10;ctx.globalAlpha=.42;ctx.fillStyle=d.c;ctx.beginPath();ctx.arc(d.x,d.y,d.r,0,Math.PI*2);ctx.fill()});requestAnimationFrame(draw)}draw()};
